//! Live native Fillet model and actual application dispatch, no rendered claim.
use glam::{DVec3,DMat4};
use ingetrazo_core::groups::Group;
use ingetrazo_core::{mesh::Mesh,scene::{Scene,SelectionItem},math::Ray};
use ingetrazo_gui::IngeTrazoApp;
use ingetrazo_tools::{fillet::fillet_edges,base::{ToolContext,ToolType}};
use serde_json::{json,Value};
fn load(v:&Value)->Mesh{let mut m=Mesh::new();for p in v["vertices"].as_array().unwrap(){m.add_vertex(point(p));}for e in v["edges"].as_array().unwrap(){let id=m.add_edge(e["ends"][0].as_u64().unwrap()as usize,e["ends"][1].as_u64().unwrap()as usize).unwrap();m.edges[id].soft=e["soft"].as_bool().unwrap();m.edges[id].hidden=e["hidden"].as_bool().unwrap();m.edges[id].curve_id=e["curve"].as_u64().map(|x|x as usize);m.edges[id].layer=e["layer"].as_str().map(str::to_owned);m.edges[id].attrs=serde_json::from_value(e["attrs"].clone()).unwrap();}for f in v["faces"].as_array().unwrap(){let ring=serde_json::from_value(f["loop"].clone()).unwrap();let holes=serde_json::from_value(f["holes"].clone()).unwrap();let id=m.add_face(ring,holes).unwrap();m.faces[id].attrs=serde_json::from_value(f["attrs"].clone()).unwrap();m.faces[id].layer=f["attrs"]["layer"].as_str().map(str::to_owned);m.faces[id].interior=f["interior"].as_bool().unwrap();}m}
fn point(v:&Value)->DVec3{DVec3::from_array(std::array::from_fn(|i|v[i].as_f64().unwrap()))}
fn snap(m:&Mesh,old:&Mesh)->Value{json!({"vertices":m.vertices.iter().map(|v|v.position.to_array()).collect::<Vec<_>>(),"vertex_origins":m.vertices.iter().map(|v|old.vertices.iter().position(|x|x.uid==v.uid)).collect::<Vec<_>>(),"edges":m.edges.iter().map(|e|json!({"ends":[e.v0,e.v1],"soft":e.soft,"curve":e.curve_id,"layer":e.layer,"hidden":e.hidden,"attrs":e.attrs,"origin":old.edges.iter().position(|x|x.history_id==e.history_id)})).collect::<Vec<_>>(),"faces":m.faces.iter().map(|f|json!({"loop":f.vertices,"holes":f.holes,"attrs":f.attrs,"interior":f.interior,"origin":old.faces.iter().position(|x|x.history_id==f.history_id)})).collect::<Vec<_>>()})}
fn state(a:&IngeTrazoApp,old:&Mesh)->Value{json!({"mesh":snap(&a.scene.mesh,old),"undo":a.undo_stack.len(),"redo":a.redo_stack.len(),"selection":a.scene.selection.len(),"preview_faces":a.active_tool.preview_mesh().map_or(0,|m|m.faces.len()),"preview_lines":a.active_tool.rubber_band_lines().len(),"status":a.status_message})}
fn ctx(p:DVec3)->ToolContext{ToolContext::new(p,Ray::new(p+DVec3::Z*10.,-DVec3::Z))}
fn main(){let args=std::env::args().collect::<Vec<_>>();let input:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let mut cases=vec![];let mut apps=vec![];
let mut recipes=input["cases"].as_array().unwrap().clone();let mut nested=recipes[0].clone();nested["name"]=json!("nested-translated");recipes.push(nested);
for row in &recipes{eprintln!("case {}",row["name"]);let mut old=load(&row["before"]);if row["name"]=="nested-translated"{old.vertices.truncate(8);old.edges.truncate(12);old.faces.truncate(6);for e in &mut old.edges{e.soft=false;e.curve_id=None;e.layer=None;e.hidden=false;}for f in &mut old.faces{f.attrs.clear();f.layer=None;f.interior=false;}old.rebuild_incidence();old.rebuild_spatial_index();}let ids:Vec<usize>=serde_json::from_value(row["selected"].clone()).unwrap();let mut s=Scene::new();s.mesh=old.clone();if row["name"]!="nested-translated" {fillet_edges(&mut s,&ids,row["radius"].as_f64().unwrap(),row["segments"].as_u64().unwrap()as usize).unwrap();cases.push(json!({"name":row["name"],"after":snap(&s.mesh,&old)}));}
 if row["name"]=="endpoint-free-wire"||row["name"]=="open-neighbor"||row["name"]=="nested-translated"{let mut a=IngeTrazoApp::new();a.system_clipboard=None;a.scene.mesh=old.clone();if row["name"]=="nested-translated" {let mut child=Group::with_mesh("child",old.clone());child.transform=DMat4::from_translation(DVec3::new(1.,2.,0.));child.native_document=json!({"component":true,"xform":child.transform.to_cols_array()});let mut outer=Group::with_mesh("outer",Mesh::new());outer.transform=DMat4::from_translation(DVec3::new(4.,5.,0.));outer.native_document=json!({"component":true,"xform":outer.transform.to_cols_array()});outer.children.push(child);a.scene.mesh=Mesh::new();a.scene.groups.push(outer);a.scene.select(SelectionItem::Group(0));a.begin_component_edit();a.scene.select(SelectionItem::Group(0));a.begin_component_edit();}let acquired=a.scene.mesh.clone();for &id in &ids{a.scene.select(SelectionItem::Edge(id));}a.set_tool(ToolType::Fillet);let mut states=serde_json::Map::new();states.insert("activate".into(),state(&a,&old));a.dispatch_tool_vcb("6s").unwrap();states.insert("segments".into(),state(&a,&old));let edge=&a.scene.mesh.edges[ids[0]];let p=(a.scene.mesh.vertices[edge.v0].position+a.scene.mesh.vertices[edge.v1].position)*0.5;a.dispatch_tool_click(&ctx(p));a.dispatch_tool_move(&ctx(p+DVec3::Y*0.25));states.insert("sizing".into(),state(&a,&old));let before=a.scene.clone();let undo=a.undo_stack.clone();let redo=a.redo_stack.clone();assert!(a.dispatch_tool_vcb("5").is_err());assert_eq!(a.scene,before);assert_eq!(a.undo_stack,undo);assert_eq!(a.redo_stack,redo);states.insert("refusal".into(),state(&a,&old));a.dispatch_tool_cancel();states.insert("cancel".into(),state(&a,&old));for &id in &ids{a.scene.select(SelectionItem::Edge(id));}a.set_tool(ToolType::Fillet);a.dispatch_tool_vcb("0.2").unwrap();states.insert("commit".into(),state(&a,&old));let accepted=a.scene.mesh.clone();a.undo();assert_eq!(a.scene.mesh,acquired);states.insert("undo".into(),state(&a,&old));a.redo();assert_eq!(a.scene.mesh,accepted);states.insert("redo".into(),state(&a,&old));if row["name"]=="nested-translated" {a.finish_component_edit();let mut st=state(&a,&old);st["mesh"]=snap(&a.scene.groups[0].mesh,&old);states.insert("finish-child".into(),st);a.finish_component_edit();let mut st=state(&a,&old);st["mesh"]=snap(&a.scene.groups[0].children[0].mesh,&old);states.insert("finish-outer".into(),st);a.undo();let mut st=state(&a,&old);st["mesh"]=snap(&a.scene.groups[0].children[0].mesh,&old);states.insert("finish-undo".into(),st);a.redo();let mut st=state(&a,&old);st["mesh"]=snap(&a.scene.groups[0].children[0].mesh,&old);states.insert("finish-redo".into(),st);}apps.push(json!({"name":row["name"],"states":states}));}
}
std::fs::write(&args[2],serde_json::to_vec_pretty(&json!({"cases":cases,"apps":apps,"scope":"native local solid model + actual App/Tool VCB/Cancel/Undo/Redo, no rendered/input-device claim"})).unwrap()).unwrap();}
